  25	///|
  26	async fn adapter_executable() -> String {
  27	  let name = @env.args()[0]
  28	  if name.contains("/") {
  29	    return @fs.realpath(name)
  30	  }
  31	  for directory in @env.get_env_var("PATH").unwrap_or("").split(":") {
  32	    let path = directory.to_owned() + "/" + name
  33	    if @fs.exists(path) {
  34	      return @fs.realpath(path)
  35	    }
  36	  }
  37	  raise AdapterError("Adapter executable is unavailable for tunnel recovery")
  38	}
