 100	///|
 101	async fn stop_tunnel_master(
 102	  state : Json,
 103	  directory : String,
 104	  verify~ : Bool = false,
 105	) -> Unit {
 106	  @async.with_timeout(2000, async fn() {
 107	    ignore(
 108	      @process.collect_output(
 109	        workspace_program(state, "ssh"),
 110	        extra_env=workspace_environment(state),
 111	        cwd?=workspace_directory(state).map(path => path[:]),
 112	        inherit_env=false,
 113	        ssh_args(state) + ["-S", control_socket(state, directory), "-O", "exit"],
 114	      ),
 115	    )
 116	  }) catch {
 117	    _ => ()
 118	  }
 119	  if verify {
 120	    @async.with_timeout(5000, async fn() {
 121	      while true {
 122	        let (code, _, _) = @process.collect_output(
 123	          workspace_program(state, "ssh"),
 124	          extra_env=workspace_environment(state),
 125	          cwd?=workspace_directory(state).map(path => path[:]),
 126	          inherit_env=false,
 127	          ssh_args(state) +
 128	          [
 129	            "-o",
 130	            "ProxyCommand=false",
 131	            "-S",
 132	            control_socket(state, directory),
 133	            "-O",
 134	            "check",
 135	          ],
 136	        )
 137	        if code != 0 {
 138	          break
 139	        }
 140	        @async.sleep(100)
 141	      }
 142	    })
 143	  }
 144	  if field(state, "socketDirectory") is Some(Json::String(socket_directory)) {
 145	    if @fs.exists(socket_directory + "/socket") {
 146	      @fs.remove(socket_directory + "/socket")
 147	    }
 148	    wait_ssh_proxy(state, "primary")
 149	    let lease = socket_directory + "/primary-proxy.lock"
 150	    if @fs.exists(lease) {
 151	      @fs.remove(lease)
 152	    }
 153	    @fs.rmdir(socket_directory) catch {
 154	      _ => ()
 155	    }
 156	  }
 157	}
