 159	///|
 160	async fn ensure_ssh_worker(
 161	  state : Json,
 162	  port : Int32?,
 163	  deadline? : UInt64,
 164	  restart~ : Bool = false,
 165	) -> Unit {
 166	  let mut expires = deadline.unwrap_or(connection_deadline())
 167	  let base = adapter_state_home() + "/tunnels"
 168	  @fs.mkdir(base, recursive=true, permission=0o700, allow_exist=true)
 169	  let directory = match field(state, "tunnelDirectory") {
 170	    Some(Json::String(old)) if old.has_prefix(base + "/") && @fs.exists(old) =>
 171	      old
 172	    _ => {
 173	      if restart &&
 174	        field(state, "tunnelDirectory") is Some(Json::String(old)) &&
 175	        @fs.exists(old) {
 176	        let lease = @fs.open(
 177	          old + "/startup.lock",
 178	          mode=ReadWrite,
 179	          create_mode=OpenOrCreate,
 180	          permission=0o600,
 181	        )
 182	        defer lease.close()
 183	        @async.with_timeout(30000, async fn() {
 184	          while !lease.try_lock(Exclusive) {
 185	            @async.sleep(100)
 186	          }
 187	        })
 188	        let saved = if @fs.exists(old + "/state.json") {
 189	          @json.parse(@fs.read_file(old + "/state.json").text())
 190	        } else {
 191	          state
 192	        }
 193	        guard field(saved, "workspaceUid") == field(state, "workspaceUid") else {
 194	          raise AdapterError("Tunnel ownership changed")
 195	        }
 196	        restart_tunnel(saved, old)
 197	        expires = connection_deadline()
 198	      }
 199	      close_tunnel(state)
 200	      let name = required(state, "workspaceUid")
 201	        .replace_all(old="%", new="%25")
 202	        .replace_all(old="/", new="%2F")
 203	      let directory = base + "/workspace-" + name
 204	      @fs.mkdir(directory, permission=0o700, allow_exist=true)
 205	      set_field(state, "tunnelDirectory", Json::string(directory))
 206	      directory
 207	    }
 208	  }
 209	  let lease = @fs.open(
 210	    directory + "/startup.lock",
 211	    mode=ReadWrite,
 212	    create_mode=OpenOrCreate,
 213	    permission=0o600,
 214	  )
 215	  defer lease.close()
 216	  @async.with_timeout(30000, async fn() {
 217	    while !lease.try_lock(Exclusive) {
 218	      @async.sleep(100)
 219	    }
 220	  })
 221	  if @fs.exists(directory + "/state.json") {
 222	    let saved = @json.parse(@fs.read_file(directory + "/state.json").text())
 223	    guard field(saved, "workspaceUid") == field(state, "workspaceUid") &&
 224	      field(saved, "localPort") ==
 225	      port.map(value => Json::number(value.to_double())) else {
 226	      raise AdapterError("Tunnel ownership changed")
 227	    }
 228	    if restart {
 229	      restart_tunnel(saved, directory)
 230	      expires = connection_deadline()
 231	    }
 232	    if !worker_alive(directory) {
 233	      @fs.write_file(directory + "/enabled", "", permission=0o600)
 234	      spawn_tunnel_worker(directory)
 235	    }
 236	    wait_tunnel(directory, expires)
 237	    return
 238	  } else if restart {
 239	    restart_tunnel(state, directory)
 240	    expires = connection_deadline()
 241	  }
 242	  let socket_directory = @fs.tmpdir(prefix="oe")
 243	  let saved = Json::empty_object()
 244	  for
 245	    name in [
 246	      "workspaceId", "workspaceUid", "orcaVolume", "orcaVolumeCleanup", "user", "command",
 247	      "devsyEnv", "hostDirectory", "home", "context", "connection", "projectRoot",
 248	      "idleTimeoutMs", "idleProvider",
 249	    ] {
 250	    if field(state, name) is Some(value) {
 251	      set_field(saved, name, value)
 252	    }
 253	  }
 254	  set_field(saved, "socketDirectory", Json::string(socket_directory))
 255	  if port is Some(value) {
 256	    set_field(saved, "localPort", Json::number(value.to_double()))
 257	  }
 258	  @fs.write_file(directory + "/state.tmp", saved.stringify(), permission=0o600)
 259	  @fs.rename(directory + "/state.tmp", directory + "/state.json", replace=true)
 260	  @fs.write_file(directory + "/enabled", "", permission=0o600)
 261	  if @fs.exists(directory + "/status.json") {
 262	    @fs.remove(directory + "/status.json")
 263	  }
 264	  spawn_tunnel_worker(directory)
 265	  wait_tunnel(directory, expires)
 266	}
