 268	///|
 269	async fn restart_tunnel(state : Json, directory : String) -> Unit {
 270	  let enabled = directory + "/enabled"
 271	  let was_enabled = @fs.exists(enabled)
 272	  errdefer (if was_enabled && @fs.exists(directory) {
 273	    @fs.write_file(enabled, "", permission=0o600) catch {
 274	      _ => ()
 275	    }
 276	  })
 277	  let mut phase = if worker_alive(directory) { "worker" } else { "master" }
 278	  save_diagnostic(
 279	    "ssh-tunnel-restart",
 280	    "started",
 281	    phase~,
 282	    tunnel_directory=directory,
 283	  )
 284	  let mut timed_out = false
 285	  errdefer save_diagnostic(
 286	    "ssh-tunnel-restart",
 287	    if timed_out {
 288	      "timeout"
 289	    } else {
 290	      "failed"
 291	    },
 292	    phase~,
 293	    error_type=if timed_out { "shutdown_timeout" } else { "shutdown_failed" },
 294	    tunnel_directory=directory,
 295	  )
 296	  try {
 297	    if @fs.exists(enabled) {
 298	      @fs.remove(enabled)
 299	    }
 300	    @async.with_timeout(15000, async fn() {
 301	      while worker_alive(directory) {
 302	        @async.sleep(100)
 303	      }
 304	    })
 305	    phase = "master"
 306	    save_diagnostic(
 307	      "ssh-tunnel-restart",
 308	      "stopping",
 309	      phase~,
 310	      tunnel_directory=directory,
 311	    )
 312	    stop_tunnel_master(state, directory, verify=true)
 313	  } catch {
 314	    @async.TimeoutError as error => {
 315	      timed_out = true
 316	      raise error
 317	    }
 318	    error => raise error
 319	  }
 320	  save_diagnostic("ssh-tunnel-restart", "success", tunnel_directory=directory)
 321	}
