 776	///|
 777	async fn tunnel_worker(directory : String) -> Unit {
 778	  let lock = @fs.open(
 779	    directory + "/worker.lock",
 780	    mode=ReadWrite,
 781	    create_mode=OpenOrCreate,
 782	    permission=0o600,
 783	  )
 784	  defer lock.close()
 785	  if !lock.try_lock(Exclusive) {
 786	    return
 787	  }
 788	  if @fs.exists(directory + "/request") {
 789	    @fs.remove(directory + "/request")
 790	  }
 791	  let state = @json.parse(@fs.read_file(directory + "/state.json").text())
 792	  validate_state(state)
 793	  let forwarding = match field(state, "localPort") {
 794	    Some(Json::Number(value, ..)) =>
 795	      ["-L", "127.0.0.1:\{value.to_int()}:127.0.0.1:47121"]
 796	    None if field(state, "connection") == Some(Json::string("ssh")) => []
 797	    _ => raise AdapterError("Missing tunnel port")
 798	  }
 799	  let enabled = directory + "/enabled"
 800	  let mut adopted = try {
 801	    check_tunnel(state, directory)
 802	    true
 803	  } catch {
 804	    _ => false
 805	  }
 806	  set_field(state, "tunnelDirectory", Json::string(directory))
 807	  let idle_timer = if idle_timeout(state) is Some(_) {
 808	    Some(IdleTimer::{ elapsed: 0, seen: false, epoch: -1, previous: None, })
 809	  } else {
 810	    None
 811	  }
 812	  let mut attempt = 0
 813	  let mut monitoring = false
 814	  let mut monitor_attempt = 0
 815	  let mut needs_cleanup = @fs.exists(control_socket(state, directory))
 816	  defer @async.protect_from_cancel(async fn() {
 817	    if needs_cleanup {
 818	      stop_tunnel_master(state, directory)
 819	    }
 820	  })
 821	  while @fs.exists(enabled) {
 822	    if pause_request(directory) is Some(request) {
 823	      if idle_timer is Some(timer) {
 824	        timer.previous = None
 825	      }
 826	      if needs_cleanup {
 827	        stop_tunnel_master(state, directory)
 828	        needs_cleanup = false
 829	      }
 830	      tunnel_status(directory, "paused")
 831	      while @fs.exists(enabled) && pause_request(directory) == Some(request) {
 832	        @fs.write_file(directory + "/pause-ack", request, permission=0o600)
 833	        @async.sleep(100)
 834	      }
 835	      continue
 836	    }
 837	    if @fs.exists(directory + "/probe-request") {
 838	      @fs.remove(directory + "/probe-request")
 839	    }
 840	    tunnel_status(directory, "connecting")
 841	    git_relay_status(directory, "pending")
 842	    let mut terminal = false
 843	    @async.with_task_group(async fn(group) {
 844	      let idle_busy : Ref[Bool] = { val: false, }
 845	      let idle_done : Ref[Bool] = { val: false, }
 846	      let mut idle_started = false
 847	      group.spawn_bg(no_wait=true, async fn() {
 848	        while @fs.exists(enabled) && !@fs.exists(directory + "/paused") {
 849	          @async.sleep(100)
 850	        }
 851	        raise AdapterError("Tunnel disabled or paused")
 852	      })
 853	      monitoring = true
 854	      let current = worker_workspace(state, directory)
 855	      save_diagnostic(
 856	        "monitor-identity",
 857	        match current {
 858	          None => "missing"
 859	          Some(value) if field(value, "uid") == field(state, "workspaceUid") =>
 860	            "matched"
 861	          _ => "replaced"
 862	        },
 863	        tunnel_directory=directory,
 864	        expected_workspace_uid=required(state, "workspaceUid"),
 865	        observed_workspace_uid?=current.map(value => required(value, "uid")),
 866	      )
 867	      guard current is Some(current) &&
 868	        field(current, "uid") == field(state, "workspaceUid") else {
 869	        if @fs.exists(enabled) {
 870	          @fs.remove(enabled)
 871	        }
 872	        terminal = true
 873	        tunnel_status(directory, "ownership-error")
 874	        return
 875	      }
 876	      let status = required(current, "workspaceStatus")
 877	      save_diagnostic("monitor-workspace", status, tunnel_directory=directory)
 878	      if status == "NotFound" {
 879	        terminal = true
 880	        @fs.remove(enabled)
 881	        tunnel_status(directory, "ownership-error")
 882	        return
 883	      }
 884	      if status != "Running" {
 885	        if status == "Stopped" {
 886	          idle_reset(state, "workspace_stopped")
 887	        }
 888	        monitoring = true
 889	        tunnel_status(
 890	          directory,
 891	          if status == "Stopped" {
 892	            "workspace-stopped"
 893	          } else {
 894	            "workspace-busy"
 895	          },
 896	        )
 897	        return
 898	      }
 899	      monitoring = false
 900	      @fs.mkdir(
 901	        required(state, "socketDirectory"),
 902	        permission=0o700,
 903	        allow_exist=true,
 904	      )
 905	      let sink = @process.redirect_to_file("/dev/null", shared=true)
 906	      defer sink.close()
 907	      let (errors, stderr) = @process.read_from_process()
 908	      defer errors.close()
 909	      let classified = group.spawn(
 910	        async fn() { tunnel_errors(errors) },
 911	        no_wait=true,
 912	      )
 913	      needs_cleanup = true
 914	      let child = if adopted {
 915	        save_diagnostic("orca-tunnel", "adopted", tunnel_directory=directory)
 916	        None
 917	      } else {
 918	        Some(
 919	          @process.spawn(
 920	            group,
 921	            workspace_program(state, "ssh"),
 922	            extra_env=workspace_environment(state),
 923	            cwd?=workspace_directory(state).map(path => path[:]),
 924	            inherit_env=false,
 925	            ssh_args(
 926	              state,
 927	              lease=required(state, "socketDirectory") + "/primary-proxy.lock",
 928	            ) +
 929	            [
 930	              "-M",
 931	              "-S",
 932	              control_socket(state, directory),
 933	              "-N",
 934	              "-o",
 935	              "ExitOnForwardFailure=yes",
 936	              "-o",
 937	              "ServerAliveInterval=10",
 938	              "-o",
 939	              "ServerAliveCountMax=3",
 940	            ] +
 941	            forwarding,
 942	            stdin=@process.redirect_from_file("/dev/null"),
 943	            stdout=sink,
 944	            stderr~,
 945	            no_wait=true,
 946	          ),
 947	        )
 948	      }
 949	      adopted = false
 950	      let git_enabled = @async.with_timeout(10000, async fn() {
 951	        git_forwarding_enabled(state)
 952	      })
 953	      let mut next_probe = @env.now()
 954	      let mut next_check = @env.now()
 955	      let mut failures = 0
 956	      let mut connected = false
 957	      while @fs.exists(enabled) {
 958	        if idle_done.val {
 959	          monitoring = true
 960	          break
 961	        }
 962	        if idle_busy.val {
 963	          @async.sleep(100)
 964	          continue
 965	        }
 966	        if child is Some(child) && child.try_wait() is Some(code) {
 967	          save_diagnostic(
 968	            "orca-tunnel",
 969	            "disconnected",
 970	            exit_code=code,
 971	            error_type=@async.with_timeout(1000, async fn() {
 972	              classified.wait()
 973	            }) catch {
 974	              _ => "process_exit"
 975	            },
 976	            tunnel_directory=directory,
 977	          )
 978	          break
 979	        }
