   108	      @process.collect_output(
   109	        workspace_program(state, "ssh"),
   110	        extra_env=workspace_environment(state),
   111	        cwd?=workspace_directory(state).map(path => path[:]),
   112	        inherit_env=false,
   113	        ssh_args(state) + ["-S", control_socket(state, directory), "-O", "exit"],
   114	      ),
   115	    )
   116	  }) catch {
   117	    _ => ()
   118	  }
   119	  if verify {
   120	    @async.with_timeout(5000, async fn() {
   121	      while true {
   122	        let (code, _, _) = @process.collect_output(
   123	          workspace_program(state, "ssh"),
   124	          extra_env=workspace_environment(state),
   125	          cwd?=workspace_directory(state).map(path => path[:]),
   126	          inherit_env=false,
   127	          ssh_args(state) +
   128	          [
   129	            "-o",
   130	            "ProxyCommand=false",
   131	            "-S",
   132	            control_socket(state, directory),
   133	            "-O",
   134	            "check",
   135	          ],
   136	        )
   137	        if code != 0 {
   138	          break
   139	        }
