   359	    return
   360	  }
   361	  let mut failures = 0
   362	  let permits = @async.Semaphore(4)
   363	  @async.with_task_group(async fn(group) {
   364	    for name in @fs.readdir(base, sort=true) {
   365	      let directory = base + "/" + name
   366	      permits.acquire()
   367	      group.spawn_bg(async fn() {
   368	        defer permits.release()
   369	        try {
   370	          if @fs.kind(directory, follow_symlink=false) !=
   371	            @fs.FileKind::Directory ||
   372	            !@fs.exists(directory + "/enabled") {
   373	            return
   374	          }
   375	          let state = @json.parse(
   376	            @fs.read_file(directory + "/state.json").text(),
   377	          )
   378	          validate_state(state)
   379	          set_field(state, "tunnelDirectory", Json::string(directory))
   380	          recover_connection(state, restart~)
   381	        } catch {
   382	          _ =>
   383	            if @fs.exists(directory) {
   384	              failures += 1
   385	              save_diagnostic("recover", "failed", tunnel_directory=directory)
   386	            } else {
   387	              save_diagnostic("recover", "target-removed")
   388	            }
   389	        }
   390	      })
   391	    }
   392	  })
   393	  guard failures == 0 else {
   394	    raise AdapterError(
   395	      "Some connections could not be recovered; other targets were attempted",
   396	    )
